// worktreeRootCache caches the worktree root to avoid repeated git commands.
// The cache is keyed by the current working directory to handle directory changes.
var (
	worktreeRootMu       sync.RWMutex
	worktreeRootCache    string
	worktreeRootCacheDir string
)

// WorktreeRoot returns the git worktree root directory — in a linked worktree
// that worktree's root, not the main repository's. The result is cached per
// working directory. Callers that need to distinguish "outside a repository"
// from "could not find out" match ErrNotARepository; nothing else may be
// read as the benign case.
//
// Everything Entire stores is located from this path — .entire via the entiredir
// package, and the git common dir via gitdir — so a failure here used to be
// papered over by callers falling back to a relative path, which then resolved
// against wherever the process happened to be. From a subdirectory that silently
// meant a second .entire beside the agent instead of the repository's one.
//
// The subprocess fails for more reasons than "no repository" — `git` off $PATH
// is the common one — so those two outcomes are separated rather than merged:
// only ErrNotARepository means "there is nothing here", and it is the only
// failure any caller is allowed to answer with a directory of its own.
func WorktreeRoot(ctx context.Context) (string, error) {
	// Get current working directory to check cache validity
	cwd, err := os.Getwd() //nolint:forbidigo // already present in codebase
	if err != nil {
		cwd = ""
	}

	// Check cache with read lock first
	worktreeRootMu.RLock()
	if worktreeRootCache != "" && worktreeRootCacheDir == cwd {
		cached := worktreeRootCache
		worktreeRootMu.RUnlock()
		return cached, nil
	}
	worktreeRootMu.RUnlock()

	root, err := resolveWorktreeRoot(ctx)
	if err != nil {
		return "", err
	}

	worktreeRootMu.Lock()
	worktreeRootCache = root
	worktreeRootCacheDir = cwd
	worktreeRootMu.Unlock()

	return root, nil
}

// resolveWorktreeRoot asks git, and treats every failure to get an answer as a
// failure — it never substitutes a guess of its own.
//
// A walk up for a .git entry was tried here and removed. It looks like a free
// improvement (it is the same search git performs, so it agrees with git
// whenever both can run) but it is not, because it can only run in the cases
// where git did NOT agree, and in every one of those git knew something the walk
// cannot see: dubious ownership fires INSIDE a repository, so walking up finds
// the .git git just refused and hands back a root the user's own git will not
// use; a GIT_DIR pointing elsewhere makes the nearest .git the wrong answer, not
// the right one. Refusing to run on a machine whose git is broken is the cheaper
// mistake, and it is the rule RequireEntireDir already states.
//
// The one thing that must not happen is a failure here becoming a path anyway.
// Callers used to fall back to a path relative to the current directory, which
// from a subdirectory silently meant a second .entire beside the agent instead
// of the repository's one. entiredir.anchor is the surviving fallback and it
// fires only on the positive ErrNotARepository verdict below.
func resolveWorktreeRoot(ctx context.Context) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
	// Force C messages so classifyWorktreeRootError can recognise git's
	// "not a repository" on a localized machine. Built by filtering rather than
	// appending, because a duplicate key in the environment resolves to the
	// first match on Unix, not the last. Everything else is inherited, so the
	// GIT_DIR/GIT_WORK_TREE a hook exports still selects the worktree.
	cmd.Env = envWithCMessages(os.Environ())

	output, err := cmd.Output()
	if err != nil {
		return "", classifyWorktreeRootError(ctx, err)
	}

	root := strings.TrimSpace(string(output))
	// Git printed no path but reported success. Whatever produced that, it is
	// not an answer, and treating "" as a worktree root resolves every repo
	// path against the filesystem root.
	if root == "" {
		return "", errors.New("git rev-parse --show-toplevel reported success but printed no path")
	}
	return root, nil
}

// ErrNotARepository reports that git positively identified the working
// directory as being outside any repository. It is the ONLY worktree-root
// failure that means "there is nothing here to look at" — every other one
// (git missing from PATH, a cancelled context, a permission failure, dubious
// ownership, malformed output) means "we could not find out", which is a
// different thing and must not be treated as the benign case.
var ErrNotARepository = errors.New("not a git repository")

// classifyWorktreeRootError separates git's "not a repository" verdict from
// every other reason `git rev-parse --show-toplevel` can fail.
//
// The distinction is load-bearing rather than cosmetic. Callers skip work when
// there is no repository, and settings resolution falls back to a path relative
// to the current directory when the root cannot be resolved — so folding an
// unexpected failure into "not a repository" turns a broken git into a silent
// read of ./.entire/settings.json, which is exactly the path a `.entire`
// symlink redirects.
//
// Identification is positive, not by elimination: git must have run and exited
// non-zero, and must have said so. Exit code 128 alone is not enough, since git
// also uses it for dubious ownership and permission failures, both of which
// happen INSIDE a repository.
func classifyWorktreeRootError(ctx context.Context, err error) error {
	// Checked first: a cancelled context kills the child, and the resulting
	// exit status carries no verdict about the repository.
	if ctxErr := ctx.Err(); ctxErr != nil {
		return fmt.Errorf("failed to get git worktree root: %w", ctxErr)
	}

	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if bytes.Contains(bytes.ToLower(exitErr.Stderr), []byte("not a git repository")) {
			return fmt.Errorf("%w: %s", ErrNotARepository, firstLine(exitErr.Stderr))
		}
		// Git's own fatal, not just the exit status. "exit status 128" names no
		// cause, and the causes here are ones the user has to act on -- most
		// often safe.directory's ownership check, whose fix is a git config the
		// message states outright.
		if line := firstLine(exitErr.Stderr); line != "" {
			return fmt.Errorf("failed to get git worktree root: %s", line)
		}
	}

	return fmt.Errorf("failed to get git worktree root: %w", err)
}

// firstLine trims git's stderr to its opening line, which carries the fatal.
func firstLine(b []byte) string {
	if i := bytes.IndexByte(b, '\n'); i >= 0 {
		b = b[:i]
	}
	return strings.TrimSpace(string(b))
}

// envWithCMessages returns env with the locale variables git consults for
// message translation replaced by C, leaving everything else untouched.
func envWithCMessages(env []string) []string {
	out := make([]string, 0, len(env)+2)
	for _, kv := range env {
		switch {
		case strings.HasPrefix(kv, "LC_ALL="),
			strings.HasPrefix(kv, "LC_MESSAGES="),
			strings.HasPrefix(kv, "LANGUAGE="),
			strings.HasPrefix(kv, "LANG="):
			continue
		}
		out = append(out, kv)
	}
	// LANGUAGE overrides LC_ALL for gettext, so both are pinned.
	return append(out, "LC_ALL=C", "LANGUAGE=")
// Package osroot provides traversal-resistant file I/O helpers built on os.Root
// (Go 1.24+). These helpers ensure that file operations cannot escape a scoped
// directory, preventing symlink attacks and TOCTOU races at the kernel level.
//
// These wrappers predate Go 1.25, which added native ReadFile/WriteFile/MkdirAll
// (etc.) on *os.Root; they remain as the codebase's stable, consistent helper
// surface and delegate to the native methods where those now exist.
//
// Errors from these functions are returned unwrapped so that callers can use
// os.IsNotExist() and errors.Is() directly without losing the original sentinel.
package osroot

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"
	"sync"
)

// ReadFile reads the named file relative to root using os.Root for
// traversal-resistant access. The kernel enforces that the read cannot
// escape the root directory, preventing symlink and TOCTOU attacks.
func ReadFile(root *os.Root, name string) ([]byte, error) {
	f, err := root.Open(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	return data, nil
}

// ReadFileNoFollow reads name while refusing a symbolic link in any component.
// os.Root already prevents a link from escaping root, but follows links whose
// targets remain inside it. Entire-owned trees require the stronger property:
// every component must identify the object stored at that name.
func ReadFileNoFollow(root *os.Root, name string) ([]byte, error) {
	f, err := OpenNoFollow(root, name)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	return data, nil
}

// OpenNoFollow opens an existing file without following any symlink component.
// Parent directories are opened and pinned one at a time; the leaf's second
// check closes its Lstat/Open race. Once verified, later replacements cannot
// redirect the open descriptor.
func OpenNoFollow(root *os.Root, name string) (*os.File, error) {
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeParent()

	before, err := parent.Lstat(leaf)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if before.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}

	f, err := parent.Open(leaf)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedFile(parent, leaf, f); err != nil {
		_ = f.Close()
		return nil, err
	}
	return f, nil
}

// OpenFileNoFollow opens or creates a file without following any symlink.
// It is intended for append-style writers: O_TRUNC is rejected because
// truncating Entire-owned writes should use an atomic temp-file-and-rename
// operation instead. Unix builds add O_NOFOLLOW to close the write-before-
// validation race; other platforms still reject pre-existing links and verify
// the opened object before returning it.
func OpenFileNoFollow(root *os.Root, name string, flag int, perm os.FileMode) (*os.File, error) {
	if flag&os.O_TRUNC != 0 {
		return nil, errors.New("osroot: OpenFileNoFollow does not permit O_TRUNC")
	}
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeParent()

	if before, err := parent.Lstat(leaf); err == nil {
		if before.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
		}
	} else if !os.IsNotExist(err) {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}

	f, err := parent.OpenFile(leaf, flag|noFollowOpenFlag, perm)
	if err != nil {
		// Preserve the package sentinel when a link appeared after the first
		// Lstat and O_NOFOLLOW rejected it.
		if info, lstatErr := parent.Lstat(leaf); lstatErr == nil && info.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
		}
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedFile(parent, leaf, f); err != nil {
		_ = f.Close()
		return nil, err
	}
	return f, nil
}

func validateOpenedFile(root *os.Root, name string, f *os.File) error {
	pathInfo, err := root.Lstat(name)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	if pathInfo.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}
	openedInfo, err := f.Stat()
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	if !os.SameFile(pathInfo, openedInfo) {
		return fmt.Errorf("%s changed while it was being opened", name)
	}
	return nil
}

// WriteFile writes data to the named file relative to root using os.Root
// for traversal-resistant access. Creates the file if it doesn't exist,
// truncates it if it does. The kernel enforces that the write cannot escape
// the root directory.
func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) (retErr error) {
	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, perm)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer func() {
		if closeErr := f.Close(); closeErr != nil && retErr == nil {
			retErr = closeErr
		}
	}()

	if _, err := f.Write(data); err != nil {
		return err //nolint:wrapcheck // preserve original error
	}
	return nil
}

// MkdirAll creates the directory named by name, along with any necessary
// parents, relative to root. The kernel enforces containment: a name that
// escapes root (absolute, or climbing above it via "..") is rejected. Already-
// existing directories are tolerated, like os.MkdirAll. This thin wrapper keeps
// the package's os.Root helper surface (alongside ReadFile/WriteFile/Remove)
// consistent at call sites.
func MkdirAll(root *os.Root, name string, perm os.FileMode) error {
	return root.MkdirAll(name, perm) //nolint:wrapcheck // preserve original error for errors.Is/os.IsNotExist
}

// Remove removes the named file relative to root using os.Root for
// traversal-resistant access. Returns nil if the file doesn't exist.
func Remove(root *os.Root, name string) error {
	err := root.Remove(name)
	if err != nil && !os.IsNotExist(err) {
		return err //nolint:wrapcheck // preserve original error
	}
	return nil
}

// ReadDir reads the named directory relative to root, returning its entries
// sorted by filename, like os.ReadDir. os.Root has no ReadDir method of its
// own, so this is the sanctioned way to list a directory without falling back
// to an unconfined os.ReadDir on a joined path.
func ReadDir(root *os.Root, name string) ([]os.DirEntry, error) {
	f, err := root.Open(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer f.Close()

	entries, err := f.ReadDir(-1)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	slices.SortFunc(entries, func(a, b os.DirEntry) int {
		return strings.Compare(a.Name(), b.Name())
	})
	return entries, nil
}

// ReadDirNoSymlinks reads a directory after opening every component beneath
// root as a real directory. Unlike ReadDir, an in-root symlink is rejected
// rather than followed.
func ReadDirNoSymlinks(root *os.Root, name string) ([]os.DirEntry, error) {
	dir, closeDir, err := OpenDirNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeDir()

	return ReadDir(dir, ".")
}

// ErrSymlinkedPath reports a symlink where a real path component was required.
// Callers match it with errors.Is.
var ErrSymlinkedPath = errors.New("path component is a symlink")

// MkdirAllNoSymlink is MkdirAll with one added refusal: if any component of
// name already exists as a symlink, it returns an error wrapping
// ErrSymlinkedPath instead of creating anything.
//
// os.Root alone is not enough here. It refuses to follow a symlink that escapes
// the root, but a symlink pointing elsewhere *inside* the root is followed
// silently, and an escaping one fails later with whatever errno the first open
// happens to hit — which surfaces to the user as an unexplained I/O failure far
// from the cause. Checking at the point the directory is established turns both
// into one named error while the caller still has the context to report it.
//
// Each component is opened relative to its already-pinned parent, including
// components created by this call. That makes creation and validation one
// descriptor-relative sequence rather than a check followed by MkdirAll.
func MkdirAllNoSymlink(root *os.Root, name string, perm os.FileMode) error {
	if name == "." {
		return nil
	}
	if !fs.ValidPath(name) {
		return fmt.Errorf("%q is not a valid root-relative path", name)
	}

	current := root
	var owned *os.Root
	defer func() {
		if owned != nil {
			_ = owned.Close()
		}
	}()
	for _, component := range strings.Split(name, "/") {
		if _, err := current.Lstat(component); os.IsNotExist(err) {
			if err := current.Mkdir(component, perm); err != nil && !errors.Is(err, fs.ErrExist) {
				return err //nolint:wrapcheck // preserve original error classification
			}
		} else if err != nil {
			return err //nolint:wrapcheck // preserve original error classification
		}
		next, err := OpenChild(current, component)
		if err != nil {
			return err
		}
		if owned != nil {
			_ = owned.Close()
		}
		owned = next
		current = next
	}
	return nil
}

