	}

	cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "rev-parse", "--git-common-dir")
	cmd.Env = gitrepo.EnvWithoutRepoOverrides()
	output, err := cmd.Output()
	if err != nil {
